package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
	"github.com/entireio/cli/cmd/entire/cli/validation"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"

	"github.com/spf13/cobra"
)

func newAttachCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "attach <session-id>",
		Short: "Attach an existing Claude Code session",
		Long: `Attach an existing Claude Code session that wasn't captured by hooks.

This creates a checkpoint from the session's transcript and registers the
session for future tracking. Use this when hooks failed to fire or weren't
installed when the session started.

The session ID is the UUID shown by 'claude --resume'.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if checkDisabledGuard(cmd.Context(), cmd.ErrOrStderr()) {
				return nil
			}
			return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0])
		},
	}
	return cmd
}

func runAttach(ctx context.Context, w io.Writer, sessionID string) error {
	logCtx := logging.WithComponent(ctx, "attach")

	// Validate session ID format
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	// Ensure we're in a git repo
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}

	// Check session isn't already tracked
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return fmt.Errorf("failed to open session store: %w", err)
	}
	existing, err := store.Load(ctx, sessionID)
	if err != nil {
		return fmt.Errorf("failed to check existing session: %w", err)
	}
	if existing != nil {
		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
	}

	// Resolve Claude Code agent and transcript path
	ag, err := agent.Get(agent.AgentNameClaudeCode)
	if err != nil {
		return fmt.Errorf("claude code agent not available: %w", err)
	}

	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
	if err != nil {
		return fmt.Errorf("failed to resolve transcript path: %w", err)
	}
	if _, statErr := os.Stat(transcriptPath); os.IsNotExist(statErr) {
		return fmt.Errorf("transcript not found at %s\nIs the session ID correct?", transcriptPath)
	}

	// Read transcript data
	transcriptData, err := ag.ReadTranscript(transcriptPath)
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}

	// Extract modified files from transcript
	var modifiedFiles []string
	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
			logging.Warn(logCtx, "failed to extract modified files from transcript")
		} else {
			modifiedFiles = files
		}
	}

	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
	changes, err := DetectFileChanges(ctx, nil)
	if err != nil {
		logging.Warn(logCtx, "failed to detect file changes")
	}

	// Filter and normalize paths
	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
	var relNewFiles, relDeletedFiles []string
	if changes != nil {
		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
	}

	// Filter to uncommitted files only
	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)

	// Ensure strategy setup
	if err := strategy.EnsureSetup(ctx); err != nil {
		logging.Warn(logCtx, "failed to ensure strategy setup")
	}

	// Create session metadata directory and copy transcript
	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
	if err != nil {
		sessionDirAbs = sessionDir
	}
	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}
	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	// Get git author
	author, err := GetGitAuthor(ctx)
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	// Extract first prompt from transcript for the commit message
	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
	commitMessage := generateCommitMessage(firstPrompt, agent.AgentTypeClaudeCode)

	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it
	strat := GetStrategy(ctx)
	if err := strat.InitializeSession(ctx, sessionID, agent.AgentTypeClaudeCode, transcriptPath, firstPrompt, ""); err != nil {
		return fmt.Errorf("failed to initialize session: %w", err)
	}

	// Update the session state with attach-specific metadata
	state, err := strategy.LoadSessionState(ctx, sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	if state != nil {
		state.CLIVersion = versioninfo.Version
		state.TranscriptPath = transcriptPath
		if err := strategy.SaveSessionState(ctx, state); err != nil {
			return fmt.Errorf("failed to save session state: %w", err)
		}
	}

	// Build step context and save checkpoint
	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)

	stepCtx := strategy.StepContext{
		SessionID:      sessionID,
		ModifiedFiles:  relModifiedFiles,
		NewFiles:       relNewFiles,
		DeletedFiles:   relDeletedFiles,
		MetadataDir:    sessionDir,
		MetadataDirAbs: sessionDirAbs,
		CommitMessage:  commitMessage,
		TranscriptPath: transcriptPath,
		AuthorName:     author.Name,
		AuthorEmail:    author.Email,
		AgentType:      agent.AgentTypeClaudeCode,
	}

	if err := strat.SaveStep(ctx, stepCtx); err != nil {
		return fmt.Errorf("failed to save checkpoint: %w", err)
	}

	// Condense session to permanent storage and generate checkpoint ID
	var checkpointIDStr string
	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
		logging.Warn(logCtx, "failed to condense session — checkpoint saved on shadow branch only")
	} else {
		// Read the checkpoint ID from the updated session state
		if condensedState, loadErr := strategy.LoadSessionState(ctx, sessionID); loadErr == nil && condensedState != nil {
			checkpointIDStr = condensedState.LastCheckpointID.String()
		}
	}

	// Transition to IDLE (attach is a completed turn)
	if finalState, loadErr := strategy.LoadSessionState(ctx, sessionID); loadErr == nil && finalState != nil {
		now := time.Now()
		finalState.LastInteractionTime = &now
		if transErr := strategy.TransitionAndLog(ctx, finalState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
			logging.Warn(logCtx, "failed to transition session to idle")
		}
		if saveErr := strategy.SaveSessionState(ctx, finalState); saveErr != nil {
			logging.Warn(logCtx, "failed to save session state after transition")
		}
	}

	// Print confirmation
	fmt.Fprintf(w, "Attached session %s\n", sessionID)
	if totalChanges > 0 {
		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
	} else {
		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
	}
	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")

	// Print checkpoint trailer for user to copy into commit message
	if checkpointIDStr != "" {
		fmt.Fprintf(w, "\nEntire-Checkpoint: %s\n", checkpointIDStr)
	}

	return nil
}

// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
func extractFirstPromptFromTranscript(data []byte) string {
	lines, err := transcript.ParseFromBytes(data)
	if err != nil {
		return ""
	}
	for _, line := range lines {
		if line.Type == "user" {
			prompt := extractTextFromMessage(line.Message)
			if prompt != "" {
				return prompt
			}
		}
	}
	return ""
}

// extractTextFromMessage extracts the text content from a transcript message.
func extractTextFromMessage(msg json.RawMessage) string {
	// Try string content first (simple user messages)
	var simple struct {
		Content string `json:"content"`
	}
	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
		return simple.Content
	}

	// Try array content (messages with tool results, text blocks, etc.)
	var array struct {
		Content []struct {
			Type string `json:"type"`
			Text string `json:"text"`
		} `json:"content"`
	}
	if err := json.Unmarshal(msg, &array); err == nil {
		for _, block := range array.Content {
			if block.Type == "text" && block.Text != "" {
				return block.Text
			}
		}
	}

	return ""
}

package cli

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
	"time"

	_ "github.com/entireio/cli/cmd/entire/cli/agent/claudecode" // register agent
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

func TestAttach_MissingSessionID(t *testing.T) {
	t.Parallel()

	cmd := newAttachCmd()
	cmd.SetArgs([]string{})

	var out bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&out)

	err := cmd.Execute()
	if err == nil {
		t.Fatal("expected error for missing session ID")
	}
}

func TestAttach_TranscriptNotFound(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "init.txt", "init")
	testutil.GitAdd(t, tmpDir, "init.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	// Enable entire
	enableEntire(t, tmpDir)

	// Set up a fake Claude project dir that's empty
	claudeDir := t.TempDir()
	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", claudeDir)

	var out bytes.Buffer
	err := runAttach(context.Background(), &out, "nonexistent-session-id")
	if err == nil {
		t.Fatal("expected error for missing transcript")
	}
}

func TestAttach_Success(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "init.txt", "init")
	testutil.GitAdd(t, tmpDir, "init.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	// Enable entire
	enableEntire(t, tmpDir)

	// Create a fake Claude transcript
	claudeDir := t.TempDir()
	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", claudeDir)

	sessionID := "test-attach-session-001"
	transcriptContent := `{"type":"user","message":{"role":"user","content":"hello"},"uuid":"uuid-1"}
{"type":"assistant","message":{"role":"assistant","content":[{"type":"tool_use","id":"tu_1","name":"Write","input":{"file_path":"` + tmpDir + `/hello.txt","content":"world"}}]},"uuid":"uuid-2"}
{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"tu_1","content":"wrote file"}]},"uuid":"uuid-3"}
`
	if err := os.WriteFile(filepath.Join(claudeDir, sessionID+".jsonl"), []byte(transcriptContent), 0o600); err != nil {
		t.Fatal(err)
	}

	// Create the file that the transcript says was modified
	testutil.WriteFile(t, tmpDir, "hello.txt", "world")

	var out bytes.Buffer
	err := runAttach(context.Background(), &out, sessionID)
	if err != nil {
		t.Fatalf("runAttach failed: %v", err)
	}

	// Verify session state was created
	store, err := session.NewStateStore(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	state, err := store.Load(context.Background(), sessionID)
	if err != nil {
		t.Fatal(err)
	}
	if state == nil {
		t.Fatal("expected session state to be created")
	}
	if state.SessionID != sessionID {
		t.Errorf("session ID = %q, want %q", state.SessionID, sessionID)
	}
	if state.LastCheckpointID.IsEmpty() {
		t.Error("expected LastCheckpointID to be set after attach")
	}

	// Verify output message
	output := out.String()
	if !strings.Contains(output, "Attached session") {
		t.Errorf("expected 'Attached session' in output, got: %s", output)
	}
}

func TestAttach_SessionAlreadyTracked(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
