			logging.Warn(logCtx, "failed to save session state after transition")
		}
	}

	// Print confirmation
	fmt.Fprintf(w, "Attached session %s\n", sessionID)
	if totalChanges > 0 {
		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
	} else {
