			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
		}
	}

	return nil
}

// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string) error {
	// Get HEAD commit info
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}
	headRef, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}
	headCommit, err := repo.CommitObject(headRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	shortHash := headRef.Hash().String()[:7]
	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]

	// Check if the commit already has this checkpoint trailer
	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
		fmt.Fprintf(w, "\nLast commit already has an Entire-Checkpoint trailer.\n")
		return nil
	}

	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)

	amend := true
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Amend to last commit in this branch?").
				Affirmative("Y").
				Negative("n").
				Value(&amend),
		),
	)
	if err := form.Run(); err != nil {
		return fmt.Errorf("prompt failed: %w", err)
	}

	if !amend {
		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
		return nil
	}

	// Amend the commit with the checkpoint trailer
	newMessage := fmt.Sprintf("%s\n\n%s: %s\n", strings.TrimRight(headCommit.Message, "\n"), trailers.CheckpointTrailerKey, checkpointIDStr)

	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
	}

	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
	return nil
}

// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
func extractFirstPromptFromTranscript(data []byte) string {
	lines, err := transcript.ParseFromBytes(data)
	if err != nil {
		return ""
	}
	for _, line := range lines {
		if line.Type == "user" {
			prompt := extractTextFromMessage(line.Message)
			if prompt != "" {
				return prompt
			}
		}
	}
	return ""
}

// extractTextFromMessage extracts the text content from a transcript message.
func extractTextFromMessage(msg json.RawMessage) string {
	// Try string content first (simple user messages)
	var simple struct {
		Content string `json:"content"`
	}
	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
		return simple.Content
	}

	// Try array content (messages with tool results, text blocks, etc.)
	var array struct {
		Content []struct {
			Type string `json:"type"`
			Text string `json:"text"`
		} `json:"content"`
	}
	if err := json.Unmarshal(msg, &array); err == nil {
		for _, block := range array.Content {
			if block.Type == "text" && block.Text != "" {
				return block.Text
			}
		}
	}

	return ""
}

